SELECT store_sales.sale_date, store_sales.revenue, stores.region, stores.store_name, stores.city, CASE WHEN store_sales.revenue >= 4100 THEN 'High' WHEN store_sales.revenue >= 1800 THEN 'Medium' ELSE 'Low' END AS revenue_tier FROM store_sales LEFT OUTER JOIN stores ON store_sales.store_id = stores.id WHERE stores.sqft < 6614 AND stores.store_name LIKE 'Ol%' ORDER BY store_sales.revenue DESC, region;
